/**
 * Unit tests for ValuedEnum#compareTo
 */
public class ValuedEnum_compareTo_TriageGen0Test {

    // Concrete implementation of ValuedEnum for testing purposes
    private enum TestEnum implements ValuedEnum {
        INSTANCE_1("INSTANCE_1", 1),
        INSTANCE_2("INSTANCE_2", 2);

        private final String name;
        private final int iValue;

        TestEnum(String name, int value) {
            this.name = name;
            this.iValue = value;
        }

        @Override
        public int getValue() {
            return iValue;
        }

        @Override
        public String toString() {
            return name;
        }
    }

    // Another enum for testing ClassCastException
    private enum DifferentEnum implements ValuedEnum {
        OTHER("OTHER", 1);

        private final String name;
        private final int iValue;

        DifferentEnum(String name, int value) {
            this.name = name;
            this.iValue = value;
        }

        @Override
        public int getValue() {
            return iValue;
        }

        @Override
        public String toString() {
            return name;
        }
    }

    @Test
    public void testCompareTo_SameInstance() {
        // if (other == this) return 1;
        // Note: The implementation provided returns 1 for identity, which is unusual for compareTo 
        // but we test according to the provided logic.
        int result = TestEnum.INSTANCE_1.compareTo(TestEnum.INSTANCE_1);
        assertEquals(1, result);
    }

    @Test
    public void testCompareTo_SameClass_DifferentValues() {
        // Normal flow: return iValue - ((ValuedEnum) other).iValue;

        // Case: this < other
        int resultLess = TestEnum.INSTANCE_1.compareTo(TestEnum.INSTANCE_2);
        assertEquals(-1, resultLess);

        // Case: this > other
        int resultGreater = TestEnum.INSTANCE_2.compareTo(TestEnum.INSTANCE_1);
        assertEquals(1, resultGreater);

